import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import {
  ComposedModal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  ComboBox,
} from 'carbon-components-react';

const items = [
  { id: 'option-1', text: 'Option 1' },
  { id: 'option-2', text: 'Option 2' },
  { id: 'option-3', text: 'Option 3' },
];

function App() {
  const [open, setOpen] = useState(false);

  return (
    <>
      <Button kind="primary" onClick={() => setOpen(true)}>
        Open Modal
      </Button>

      {typeof document !== 'undefined'
        ? ReactDOM.createPortal(
            <ComposedModal
              open={open}
              onClose={() => setOpen(false)}
              // ONLY hyphen-case works:
              aria-label="My Modal Hyphen Label"
              // -> ariaLabel (camelCase) is ignored here
              ariaLabel="Ignored Modal CamelLabel"
            >
              <ModalHeader
                // Only this hyphen-case prop takes effect
                aria-label="Header Hyphen Label"
                // this camelCase variant is ignored
                ariaLabel="Ignored Header CamelLabel"
                label="Modal label"
              />
              <ModalBody>
                <p>This demonstrates that Modal only accepts 'aria-label'.</p>
              </ModalBody>
              <ModalFooter
                primaryButtonText="Primary"
                secondaryButtonText="Secondary"
              />
            </ComposedModal>,
            document.body
          )
        : null}

      <div style={{ marginTop: '2rem', width: '300px' }}>
        {/* ComboBox only listens to camelCase 'ariaLabel' */}
        <ComboBox
          items={items}
          label="Choose an option"
          // ONLY camelCase works:
          ariaLabel="My ComboBox CamelLabel"
          // -> hyphen-case prop is ignored
          aria-label="Ignored ComboBox HyphenLabel"
        />
      </div>
    </>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
